export PKG_CONFIG_PATH=/work/lib/pkgconfig
pushd $SRC/zlib
./configure --static --prefix=$WORK
make -j$(nproc) all
make install
popd
pushd $SRC/libexif
autoreconf -fi
./configure   --enable-shared=no   --disable-docs   --disable-dependency-tracking   --prefix=$WORK
make -j$(nproc)
make install
popd
pushd $SRC/libjpeg-turbo
cmake . -DCMAKE_INSTALL_PREFIX=$WORK -DENABLE_STATIC:bool=on
make -j$(nproc)
make install
popd
pushd $SRC/libpng
sed -ie "s/option WARNING /option WARNING disabled/" scripts/pnglibconf.dfa
autoreconf -fi
./configure   --prefix=$WORK   --disable-shared   --disable-dependency-tracking
make -j$(nproc)
make install
popd
pushd $SRC/libgif
make libgif.a libgif.so install-include install-lib OFLAGS="-O2" PREFIX=$WORK
popd
pushd $SRC/libwebp
autoreconf -fi
./configure   --enable-libwebpdemux   --enable-libwebpmux   --disable-shared   --disable-jpeg   --disable-tiff   --disable-gif   --disable-wic   --disable-threading   --disable-dependency-tracking   --prefix=$WORK
make -j$(nproc)
make install
popd
pushd $SRC/libtiff
autoreconf -fi
./configure   --disable-lzma   --disable-shared   --disable-dependency-tracking   --prefix=$WORK
make -j$(nproc)
make install
popd
./autogen.sh   --disable-shared   --disable-gtk-doc   --disable-gtk-doc-html   --disable-dependency-tracking   --prefix=$WORK
make -j$(nproc) CCLD=$CXX
make install
mkdir -p fuzz/corpus
find   $SRC/afl-testcases/{gif*,jpeg*,png,tiff,webp}/full/images   fuzz/*_fuzzer_corpus   test/test-suite/images   -type f -size -2k   -exec bash -c 'hash=($(sha1sum {})); mv {} fuzz/corpus/$hash' ';'
zip -jrq $OUT/seed_corpus.zip fuzz/corpus
for fuzzer in fuzz/*_fuzzer.cc; do
  target=$(basename "$fuzzer" .cc)
  $CXX $CXXFLAGS -std=c++11 "$fuzzer" -o "$OUT/$target"     -I$WORK/include     -I/usr/include/glib-2.0     -I/usr/lib/x86_64-linux-gnu/glib-2.0/include     $WORK/lib/libvips.a     $WORK/lib/libexif.a     $WORK/lib/libturbojpeg.a     $WORK/lib/libpng.a     $WORK/lib/libz.a     $WORK/lib/libgif.a     $WORK/lib/libwebpmux.a     $WORK/lib/libwebpdemux.a     $WORK/lib/libwebp.a     $WORK/lib/libtiff.a     $LIB_FUZZING_ENGINE     -Wl,-Bstatic     -lfftw3 -lgmodule-2.0 -lgobject-2.0 -lffi -lglib-2.0 -lpcre -lexpat     -Wl,-Bdynamic -pthread
  ln -sf "seed_corpus.zip" "$OUT/${target}_seed_corpus.zip"
done
find fuzz -name '*_fuzzer.dict' -exec cp -v '{}' $OUT ';'
find fuzz -name '*_fuzzer.options' -exec cp -v '{}' $OUT ';'
